// FILE: banking-routes.ts
import { Component } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { provideRouter, RouterLink, RouterOutlet, Routes } from '@angular/router';

@Component({ standalone: true, template: '<h2>Accounts</h2><p>Fictional balances only.</p>' })
export class AccountsComponent {}

@Component({ standalone: true, template: '<h2>Transactions</h2><p>Demo history.</p>' })
export class TransactionsComponent {}

const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'accounts' },
  { path: 'accounts', component: AccountsComponent },
  { path: 'transactions', component: TransactionsComponent },
  { path: '**', redirectTo: 'accounts' }
];

@Component({
  standalone: true, imports: [RouterLink, RouterOutlet],
  template: `
    <nav aria-label="Banking navigation">
      <a routerLink="/accounts">Accounts</a>
      <a routerLink="/transactions">Transactions</a>
    </nav>
    <main><router-outlet /></main>
  `
})
export class AppComponent {}

bootstrapApplication(AppComponent, { providers: [provideRouter(routes)] });

