import { AsyncPipe } from '@angular/common';
import { Component, inject } from '@angular/core';
import { ActivatedRoute, RouterLink, Routes } from '@angular/router';
import { map } from 'rxjs';

@Component({
  standalone: true,
  selector: 'app-product-detail',
  imports: [AsyncPipe, RouterLink],
  template: `
    @if (productId$ | async; as productId) {
      <h1>Product {{ productId }}</h1>
    } @else { <p>Invalid product ID</p> }
    <p>Referral: {{ referral$ | async }}</p>
    <a routerLink="/products" [queryParams]="{ sort: 'price', page: 2 }">
      Back to sorted catalog
    </a>
  `
})
export class ProductDetailComponent {
  private readonly route = inject(ActivatedRoute);
  readonly productId$ = this.route.paramMap.pipe(
    map(params => params.get('id')),
    map(id => id !== null && /^[0-9]+$/.test(id) ? id : null)
  );
  readonly referral$ = this.route.queryParamMap.pipe(
    map(params => params.get('ref') ?? 'none')
  );
}

export const productRoutes: Routes = [
  { path: 'products/:id', component: ProductDetailComponent }
];

