import { Component, Injectable, inject } from '@angular/core';
import { CanActivateFn, Router, Routes } from '@angular/router';

@Injectable({ providedIn: 'root' })
export class DemoSession {
  // Teaching stub only: real sessions come from authenticated server flows.
  readonly signedIn = false;
}

export const sessionGuard: CanActivateFn = (_route, state) => {
  const session = inject(DemoSession);
  const router = inject(Router);
  return session.signedIn
    ? true
    : router.createUrlTree(['/sign-in'], {
        queryParams: { returnUrl: state.url }
      });
};

@Component({ standalone: true, template: '<h1>Administration</h1>' })
export class AdminComponent {}

@Component({ standalone: true, template: '<h1>Sign in</h1>' })
export class SignInComponent {}

export const guardedRoutes: Routes = [
  { path: 'admin', component: AdminComponent, canActivate: [sessionGuard] },
  { path: 'sign-in', component: SignInComponent }
];

