import { Component } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';

@Component({
  standalone: true, selector: 'app-appointment-form',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="appointment" (ngSubmit)="submit()">
      <label for="patient">Patient display name</label>
      <input id="patient" formControlName="patient" />
      @if (appointment.controls.patient.touched && appointment.controls.patient.invalid) {
        <p role="alert">Enter at least two characters.</p>
      }
      <label for="doctor">Clinician ID</label>
      <input id="doctor" formControlName="doctorId" />
      <button type="submit">Request appointment</button>
    </form>
  `
})
export class AppointmentFormComponent {
  readonly appointment = new FormGroup({
    patient: new FormControl('', {
      nonNullable: true, validators: [Validators.required, Validators.minLength(2)]
    }),
    doctorId: new FormControl('', {
      nonNullable: true, validators: [Validators.required]
    })
  });

  submit(): void {
    this.appointment.markAllAsTouched();
    if (this.appointment.invalid) return;
    const request = this.appointment.getRawValue();
    console.log('Demo payload only; send using a secure API service', request);
  }
}

