import { Component } from '@angular/core';
import {
  AbstractControl, FormControl, FormGroup, ReactiveFormsModule,
  ValidationErrors, Validators
} from '@angular/forms';

function passwordsMatch(group: AbstractControl): ValidationErrors | null {
  const password = group.get('password')?.value;
  const confirm = group.get('confirmPassword')?.value;
  return password === confirm ? null : { passwordMismatch: true };
}

@Component({
  standalone: true, selector: 'app-registration', imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" novalidate>
      <label for="name">Name</label>
      <input id="name" formControlName="name" autocomplete="name" />
      @if (submitted && form.controls.name.invalid) {
        <p role="alert">Name is required.</p>
      }
      <label for="email">Email</label>
      <input id="email" type="email" formControlName="email" autocomplete="email" />
      @if (submitted && form.controls.email.invalid) {
        <p role="alert">Enter a valid email.</p>
      }
      <label for="password">Password</label>
      <input id="password" type="password" formControlName="password" autocomplete="new-password" />
      @if (submitted && form.controls.password.invalid) {
        <p role="alert">Use at least 12 characters.</p>
      }
      <label for="confirm">Confirm password</label>
      <input id="confirm" type="password" formControlName="confirmPassword" autocomplete="new-password" />
      @if (submitted && form.controls.confirmPassword.invalid) {
        <p role="alert">Please confirm your password.</p>
      }
      @if (submitted && form.hasError('passwordMismatch')) {
        <p role="alert">Passwords do not match.</p>
      }
      <button type="submit">Register</button>
      @if (submitted && form.valid) {
        <p role="status">Demo form valid. Connect a secure identity API.</p>
      }
    </form>
  `
})
export class RegistrationComponent {
  submitted = false;
  readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: [Validators.required] }),
    email: new FormControl('', { nonNullable: true,
      validators: [Validators.required, Validators.email] }),
    password: new FormControl('', { nonNullable: true,
      validators: [Validators.required, Validators.minLength(12)] }),
    confirmPassword: new FormControl('', { nonNullable: true,
      validators: [Validators.required] })
  }, { validators: passwordsMatch });

  submit(): void {
    this.submitted = true;
    this.form.markAllAsTouched();
    if (this.form.invalid) return;
    const { name, email } = this.form.getRawValue();
    // Demo only: do not log passwords or pretend registration succeeded.
    void { name, email }; // Wire into a typed secure registration service.
  }
}
